export async function townCustomBuildings(project,layerCount,encodeAtlas){const templates=[],assets=[];for(const t of(project.buildingTemplates||[]).slice(0,64)){const art=project.assets.find(a=>a.id===t.assetId);if(!art)continue;const im=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=art.data||art.src;}),width=t.w*16,height=t.h*16,c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.drawImage(im,t.sx||0,t.sy||0,width,height,0,0,width,height);const pixels=ctx.getImageData(0,0,width,height).data;let alpha=false;for(let i=3;i<pixels.length;i+=4)if(!pixels[i]){alpha=true;break;}if(!alpha)continue;const id='town-custom-'+t.id+'-'+(globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)),planeAssetIds=[];for(let l=0;l<layerCount;l++){const assetId=id+'-'+l;planeAssetIds.push(assetId);assets.push({id:assetId,name:t.name+' · plane '+l,width,height,tileSize:16,data:await encodeAtlas({width,height,pixels:l?new Uint8ClampedArray(pixels.length):pixels})});}const mask=Array.from({length:t.w*t.h},(_,i)=>{for(let y=0;y<16;y++)for(let x=0;x<16;x++)if(pixels[((Math.floor(i/t.w)*16+y)*width+i%t.w*16+x)*4+3])return true;return false;}),rules=mask.map((v,i)=>{const door=i%t.w===t.entrance.x&&Math.floor(i/t.w)===t.entrance.y,choice=t.collisionMask?.[Math.floor(i/t.w)]?.[i%t.w],block=choice===undefined?v&&!door:choice===1;return{mode:choice===2?'behind':block?'block':'walk',collision:block?1:0,elevation:3,behavior:0,layerType:choice===2?2:1};});templates.push({id,name:t.name,category:'Other · Buildings',profileId:'other',sourceName:'Other',sourceId:'asset-pack',sourceKey:null,atlasId:'asset-pack',layerCount,w:t.w,h:t.h,layers:Object.fromEntries(['ground','details','objects','overhead'].map(k=>[k,Array(t.w*t.h).fill(null)])),rules,entrances:[{...t.entrance,target:null,warp:0}],overlay:{version:2,planeAssetIds,mask},preview:assets[assets.length-layerCount].data});}return{templates,assets};}
